33	class RestGatewayNode : public rclcpp::Node {
34	 public:
35	  explicit RestGatewayNode(const rclcpp::NodeOptions& options = rclcpp::NodeOptions())
36	      : rclcpp::Node("rest_gateway_node", options) {
37	    declare_parameter("port", 8080);
38	    declare_parameter("html_path", "tools/operator_console.html");
39	    port_ = get_parameter("port").as_int();
40	    html_path_ = get_parameter("html_path").as_string();
41	
42	    submit_cli_ = create_client<amr_dispatcher_interfaces::srv::SubmitOrder>("/dispatcher/submit_order");
43	    cancel_cli_ = create_client<amr_dispatcher_interfaces::srv::CancelOrder>("/dispatcher/cancel_order");
44	    readiness_cli_ = create_client<amr_dispatcher_interfaces::srv::GetSystemReadiness>("/system/ready");
45	
46	    estop_pub_ = create_publisher<std_msgs::msg::Bool>("/safety/estop", 10);
47	
48	    state_sub_ = create_subscription<amr_dispatcher_interfaces::msg::DispatcherState>(
49	        "/dispatcher/state", 10,
50	        [this](const amr_dispatcher_interfaces::msg::DispatcherState::SharedPtr msg) {
51	          std::lock_guard<std::mutex> lock(data_mutex_);
52	          latest_state_ = *msg;
53	        });
54	
55	    safety_sub_ = create_subscription<amr_dispatcher_interfaces::msg::SafetyState>(
56	        "/safety/state", 10,
57	        [this](const amr_dispatcher_interfaces::msg::SafetyState::SharedPtr msg) {
58	          std::lock_guard<std::mutex> lock(data_mutex_);
59	          latest_safety_ = *msg;
60	          safety_seen_ = true;
61	        });
62	
63	    link_sub_ = create_subscription<amr_dispatcher_interfaces::msg::ChassisLinkHealth>(
64	        "/chassis/link_health", 10,
65	        [this](const amr_dispatcher_interfaces::msg::ChassisLinkHealth::SharedPtr msg) {
66	          std::lock_guard<std::mutex> lock(data_mutex_);
67	          latest_link_ = *msg;
68	        });
69	
70	    event_sub_ = create_subscription<amr_dispatcher_interfaces::msg::MissionEvent>(
71	        "/dispatcher/events", 20,
72	        [this](const amr_dispatcher_interfaces::msg::MissionEvent::SharedPtr msg) {
73	          std::lock_guard<std::mutex> lock(data_mutex_);
74	          recent_events_.push_back(*msg);
75	          if (recent_events_.size() > 50) {
76	            recent_events_.erase(recent_events_.begin());
77	          }
78	        });
79	
80	    server_thread_ = std::thread(&RestGatewayNode::RunServer, this);
81	    RCLCPP_INFO(get_logger(), "REST Gateway started on port %d", port_);
82	  }
83	
84	  ~RestGatewayNode() override {
85	    running_ = false;
86	    if (server_fd_ >= 0) {
87	      close(server_fd_);
88	    }
89	    if (server_thread_.joinable()) {
90	      server_thread_.join();
91	    }
92	  }
