94	 private:
95	  void RunServer() {
96	    server_fd_ = socket(AF_INET, SOCK_STREAM, 0);
97	    if (server_fd_ < 0) {
98	      RCLCPP_ERROR(get_logger(), "Failed to create socket");
99	      return;
100	    }
101	
102	    int opt = 1;
103	    setsockopt(server_fd_, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
104	
105	    sockaddr_in address{};
106	    address.sin_family = AF_INET;
107	    address.sin_addr.s_addr = INADDR_ANY;
108	    address.sin_port = htons(port_);
109	
110	    if (bind(server_fd_, (struct sockaddr*)&address, sizeof(address)) < 0) {
111	      RCLCPP_ERROR(get_logger(), "Socket bind failed on port %d", port_);
112	      return;
113	    }
114	
115	    if (listen(server_fd_, 10) < 0) {
116	      RCLCPP_ERROR(get_logger(), "Socket listen failed");
117	      return;
118	    }
119	
120	    while (running_ && rclcpp::ok()) {
121	      sockaddr_in client_addr{};
122	      socklen_t client_len = sizeof(client_addr);
123	      int client_fd = accept(server_fd_, (struct sockaddr*)&client_addr, &client_len);
124	      if (client_fd < 0) {
125	        if (!running_) break;
126	        continue;
127	      }
128	      HandleClient(client_fd);
129	      close(client_fd);
130	    }
131	  }
132	
133	  void HandleClient(int client_fd) {
134	    std::string request;
135	    char buffer[4096] = {0};
136	    ssize_t bytes_read = read(client_fd, buffer, sizeof(buffer) - 1);
137	    if (bytes_read <= 0) return;
138	    request.append(buffer, bytes_read);
139	
140	    // 检查 Content-Length，支持完整的长请求流读取
141	    auto cl_pos = request.find("Content-Length: ");
142	    if (cl_pos != std::string::npos) {
143	      size_t cl_end = request.find("\r\n", cl_pos);
144	      if (cl_end != std::string::npos) {
145	        int content_len = std::stoi(request.substr(cl_pos + 16, cl_end - (cl_pos + 16)));
146	        size_t header_end = request.find("\r\n\r\n");
147	        if (header_end != std::string::npos) {
148	          size_t body_len = request.size() - (header_end + 4);
149	          while (body_len < static_cast<size_t>(content_len)) {
150	            bytes_read = read(client_fd, buffer, sizeof(buffer) - 1);
151	            if (bytes_read <= 0) break;
152	            request.append(buffer, bytes_read);
153	            body_len += bytes_read;
154	          }
155	        }
156	      }
157	    }
158	
159	    std::istringstream req_stream(request);
160	    std::string method, path;
161	    req_stream >> method >> path;
162	
163	    std::string response_body;
164	    std::string content_type = "application/json";
165	    std::string status_code = "200 OK";
166	
167	    if (method == "OPTIONS") {
168	      status_code = "204 No Content";
169	      response_body = "";
170	    } else if (method == "GET" && (path == "/" || path == "/index.html")) {
171	      content_type = "text/html; charset=utf-8";
172	      response_body = ReadStaticHtml();
173	      if (response_body.empty()) {
174	        status_code = "404 Not Found";
175	        response_body = "<h1>404 Not Found: operator_console.html</h1>";
176	      }
177	    } else if (method == "GET" && (path == "/api/operator/snapshot" || path == "/api/v1/state")) {
178	      response_body = FormatSnapshotJson();
179	    } else if (method == "GET" && path == "/api/system/ready") {
180	      if (readiness_cli_->wait_for_service(500ms)) {
181	        auto req = std::make_shared<amr_dispatcher_interfaces::srv::GetSystemReadiness::Request>();
182	        auto fut = readiness_cli_->async_send_request(req);
183	        if (fut.wait_for(1s) == std::future_status::ready) {
184	          auto res = fut.get();
185	          response_body = "{\"ready\":" + std::string(res->ready ? "true" : "false") +
186	                          ",\"healthy\":" + std::string(res->healthy ? "true" : "false") +
187	                          ",\"state\":\"" + res->state + "\",\"message\":\"" + res->message + "\"}";
188	          if (!res->ready) status_code = "503 Service Unavailable";
189	        } else {
190	          status_code = "504 Gateway Timeout";
191	          response_body = "{\"error\":\"readiness_probe_timeout\"}";
192	        }
193	      } else {
194	        status_code = "503 Service Unavailable";
195	        response_body = "{\"ready\":false,\"state\":\"INITIALIZING\",\"message\":\"Lifecycle Coordinator not ready\"}";
196	      }
197	    } else if (method == "POST" && path.find("/api/v1/orders") != std::string::npos) {
198	      // /api/v1/orders?id=m1&from=A&to=B&prio=5&idempotency_key=k123
199	      auto q_pos = path.find('?');
200	      if (q_pos != std::string::npos) {
201	        std::string query = path.substr(q_pos + 1);
202	        std::string mid = GetQueryParam(query, "id");
203	        std::string from = GetQueryParam(query, "from");
204	        std::string to = GetQueryParam(query, "to");
205	        int prio = std::stoi(GetQueryParam(query, "prio", "5"));
206	        std::string ikey = GetQueryParam(query, "idempotency_key");
207	
208	        if (!ikey.empty() && seen_idempotency_keys_.find(ikey) != seen_idempotency_keys_.end()) {
209	          response_body = "{\"status\":\"ignored\",\"reason\":\"idempotent_duplicate\"}";
210	        } else {
211	          if (!ikey.empty()) seen_idempotency_keys_.insert(ikey);
212	          auto req = std::make_shared<amr_dispatcher_interfaces::srv::SubmitOrder::Request>();
213	          req->mission_id = mid;
214	          req->pickup_station = from;
215	          req->dropoff_station = to;
216	          req->priority = prio;
217	
218	          if (submit_cli_->wait_for_service(1s)) {
219	            auto fut = submit_cli_->async_send_request(req);
220	            if (fut.wait_for(2s) == std::future_status::ready) {
221	              auto res = fut.get();
222	              response_body = "{\"status\":\"ok\",\"accepted\":" + std::string(res->accepted ? "true" : "false") +
223	                              ",\"mission_id\":\"" + res->mission_id + "\"}";
224	            } else {
225	              status_code = "504 Gateway Timeout";
226	              response_body = "{\"error\":\"timeout\"}";
227	            }
228	          } else {
229	            status_code = "503 Service Unavailable";
230	            response_body = "{\"error\":\"service_unavailable\"}";
231	          }
232	        }
233	      } else {
234	        status_code = "400 Bad Request";
235	        response_body = "{\"error\":\"missing_query_parameters\"}";
236	      }
237	    } else if (method == "POST" && (path.find("/api/v1/cancel") != std::string::npos || path.find("/api/workflows/cancel") != std::string::npos)) {
238	      auto q_pos = path.find('?');
239	      std::string mid;
240	      if (q_pos != std::string::npos) {
241	        mid = GetQueryParam(path.substr(q_pos + 1), "id");
242	      }
243	      auto req = std::make_shared<amr_dispatcher_interfaces::srv::CancelOrder::Request>();
244	      req->mission_id = mid;
245	      if (cancel_cli_->wait_for_service(1s)) {
246	        auto fut = cancel_cli_->async_send_request(req);
247	        if (fut.wait_for(2s) == std::future_status::ready) {
248	          auto res = fut.get();
249	          response_body = "{\"status\":\"ok\",\"canceled\":" + std::string(res->success ? "true" : "false") + "}";
250	        } else {
251	          status_code = "504 Gateway Timeout";
252	          response_body = "{\"error\":\"timeout\"}";
253	        }
254	      } else {
255	        status_code = "503 Service Unavailable";
256	        response_body = "{\"error\":\"service_unavailable\"}";
257	      }
258	    } else if (method == "POST" && path == "/api/operator/estop") {
259	      std_msgs::msg::Bool estop_msg;
260	      estop_msg.data = true;
261	      estop_pub_->publish(estop_msg);
262	      response_body = "{\"status\":\"ok\",\"estop_engaged\":true}";
263	    } else {
264	      status_code = "404 Not Found";
265	      response_body = "{\"error\":\"not_found\"}";
266	    }
267	
268	    std::ostringstream resp;
269	    resp << "HTTP/1.1 " << status_code << "\r\n";
270	    resp << "Content-Type: " << content_type << "\r\n";
271	    resp << "Content-Length: " << response_body.size() << "\r\n";
272	    resp << "Access-Control-Allow-Origin: *\r\n";
273	    resp << "Access-Control-Allow-Methods: GET, POST, OPTIONS\r\n";
274	    resp << "Connection: close\r\n\r\n";
275	    resp << response_body;
276	
277	    std::string resp_str = resp.str();
278	    write(client_fd, resp_str.c_str(), resp_str.size());
279	  }
