281	  std::string ReadStaticHtml() {
282	    std::ifstream file(html_path_);
283	    if (file.is_open()) {
284	      return std::string((std::istreambuf_iterator<char>(file)),
285	                         std::istreambuf_iterator<char>());
286	    }
287	
288	    // 1. 尝试当前工作区 tools/ 相对目录
289	    std::ifstream fallback("tools/operator_console.html");
290	    if (fallback.is_open()) {
291	      return std::string((std::istreambuf_iterator<char>(fallback)),
292	                         std::istreambuf_iterator<char>());
293	    }
294	
295	    // 2. 尝试容器内 /workspace/src/amr_dispatcher_all/tools/operator_console.html
296	    std::ifstream container_file("/workspace/src/amr_dispatcher_all/tools/operator_console.html");
297	    if (container_file.is_open()) {
298	      return std::string((std::istreambuf_iterator<char>(container_file)),
299	                         std::istreambuf_iterator<char>());
300	    }
301	
302	    // 3. 尝试 ament 包 share 路径
303	    try {
304	      std::string share_dir = ament_index_cpp::get_package_share_directory("amr_dispatcher_tools");
305	      std::ifstream share_file(share_dir + "/tools/operator_console.html");
306	      if (share_file.is_open()) {
307	        return std::string((std::istreambuf_iterator<char>(share_file)),
308	                           std::istreambuf_iterator<char>());
309	      }
310	    } catch (...) {
311	      // 忽略 ament 寻找异常
312	    }
313	
314	    return "";
315	  }
316	
317	  std::string GetQueryParam(const std::string& query, const std::string& key, const std::string& fallback = "") {
318	    std::string target = key + "=";
319	    auto pos = query.find(target);
320	    if (pos == std::string::npos) return fallback;
321	    auto end = query.find('&', pos);
322	    if (end == std::string::npos) {
323	      return query.substr(pos + target.size());
324	    }
325	    return query.substr(pos + target.size(), end - (pos + target.size()));
326	  }
327	
328	  std::string FormatSnapshotJson() {
329	    std::lock_guard<std::mutex> lock(data_mutex_);
330	    std::ostringstream os;
331	    os << "{"
332	       << "\"comparator\":\"" << latest_state_.current_comparator << "\","
333	       << "\"strategy\":\"" << latest_state_.current_comparator << "\","
334	       << "\"queue_size\":" << latest_state_.queue_size << ","
335	       << "\"queue_capacity\":" << latest_state_.queue_capacity << ","
336	       << "\"active_count\":" << latest_state_.active_missions_count << ","
337	       << "\"active_mission_id\":\"" << latest_state_.active_mission_id << "\","
338	       << "\"deadlock\":" << (latest_state_.deadlock_detected ? "true" : "false") << ","
339	       << "\"deadlock_detected\":" << (latest_state_.deadlock_detected ? "true" : "false") << ","
340	       // 未收到任何 SafetyState 时不渲染急停（默认值会误报 estop）
341	       << "\"estop_active\":" << ((safety_seen_ && !latest_safety_.motion_allowed) ? "true" : "false") << ","
342	       << "\"safety_severity\":\"" << (latest_safety_.severity.empty() ? "INFO" : latest_safety_.severity) << "\","
343	       << "\"chassis_backend\":\"" << (latest_link_.backend_name.empty() ? "Serial/Mock" : latest_link_.backend_name) << "\","
344	       << "\"chassis_healthy\":" << (latest_link_.is_healthy ? "true" : "false") << ","
345	       << "\"chassis_loss_rate\":" << latest_link_.loss_rate << ","
346	       << "\"recent_events\":[";
347	
348	    for (size_t i = 0; i < recent_events_.size(); ++i) {
349	      const auto& ev = recent_events_[i];
350	      os << "{\"mission_id\":\"" << ev.mission_id << "\",\"event\":\"" << ev.event
351	         << "\",\"reason\":\"" << ev.reason << "\"}";
352	      if (i + 1 < recent_events_.size()) os << ",";
353	    }
354	    os << "]}";
355	    return os.str();
356	  }
