359	  std::string html_path_{"tools/operator_console.html"};
360	  int server_fd_ = -1;
361	  std::atomic<bool> running_{true};
362	  std::thread server_thread_;
363	  std::mutex data_mutex_;
364	  std::unordered_set<std::string> seen_idempotency_keys_;
365	
366	  rclcpp::Client<amr_dispatcher_interfaces::srv::SubmitOrder>::SharedPtr submit_cli_;
367	  rclcpp::Client<amr_dispatcher_interfaces::srv::CancelOrder>::SharedPtr cancel_cli_;
368	  rclcpp::Client<amr_dispatcher_interfaces::srv::GetSystemReadiness>::SharedPtr readiness_cli_;
369	  rclcpp::Publisher<std_msgs::msg::Bool>::SharedPtr estop_pub_;
370	
371	  rclcpp::Subscription<amr_dispatcher_interfaces::msg::DispatcherState>::SharedPtr state_sub_;
372	  rclcpp::Subscription<amr_dispatcher_interfaces::msg::SafetyState>::SharedPtr safety_sub_;
373	  rclcpp::Subscription<amr_dispatcher_interfaces::msg::ChassisLinkHealth>::SharedPtr link_sub_;
374	  rclcpp::Subscription<amr_dispatcher_interfaces::msg::MissionEvent>::SharedPtr event_sub_;
375	
376	  amr_dispatcher_interfaces::msg::DispatcherState latest_state_;
377	  amr_dispatcher_interfaces::msg::SafetyState latest_safety_;
378	  amr_dispatcher_interfaces::msg::ChassisLinkHealth latest_link_;
379	  std::vector<amr_dispatcher_interfaces::msg::MissionEvent> recent_events_;
380	  bool safety_seen_ = false;
381	};
382	
383	}  // namespace amr_dispatcher_tools
384	
385	int main(int argc, char* argv[]) {
386	  rclcpp::init(argc, argv);
387	  auto node = std::make_shared<amr_dispatcher_tools::RestGatewayNode>();
388	  rclcpp::spin(node);
389	  rclcpp::shutdown();
390	  return 0;
391	}
